	private enum Position {
		SUBJECT,
		PREDICATE,
		OBJECT,
		CONTEXT;

		Value value() {
			return value(STATEMENT);
		}

		Value value(Statement statement) {
			return switch (this) {
			case SUBJECT -> statement.getSubject();
			case PREDICATE -> statement.getPredicate();
			case OBJECT -> statement.getObject();
			case CONTEXT -> statement.getContext();
			};
		}
	}

	private enum EntryPoint {
		ITERATE,
		EXISTS,
		COUNT;

		long count(StatementPatternQueryEvaluationStep step, BindingSet bindings) {
			if (this == EXISTS) {
				return step.hasStatement(bindings) ? 1 : 0;
			}
			if (this == COUNT) {
				return step.getFullyBoundStatementCount(bindings);
			}
			long count = 0;
			try (CloseableIteration<BindingSet> rows = step.evaluate(bindings)) {
				while (rows.hasNext()) {
					rows.next();
					count++;
				}
			}
			return count;
		}
	}

