	private static final class MatchingSource implements TripleSource {
		final Statement statement;
		int lookups;

		MatchingSource(Statement statement) {
			this.statement = statement;
		}

		@Override
		public CloseableIteration<? extends Statement> getStatements(Resource subject, IRI predicate, Value object,
				Resource... contexts) {
			lookups++;
			List<Statement> matches = matches(subject, predicate, object, contexts) ? List.of(statement) : List.of();
			return new CloseableIteratorIteration<>(matches.iterator());
		}

		@Override
		public boolean hasStatements(Resource subject, IRI predicate, Value object, Resource... contexts) {
			lookups++;
			return matches(subject, predicate, object, contexts);
		}

		@Override
		public long getStatementCount(Resource subject, IRI predicate, Value object, Resource... contexts) {
			lookups++;
			return matches(subject, predicate, object, contexts) ? 1 : 0;
		}

		private boolean matches(Resource subject, IRI predicate, Value object, Resource[] contexts) {
			return (subject == null || subject.equals(statement.getSubject()))
					&& (predicate == null || predicate.equals(statement.getPredicate()))
					&& (object == null || object.equals(statement.getObject()))
					&& (contexts.length == 0 || Arrays.asList(contexts).contains(statement.getContext()));
		}

		@Override
		public ValueFactory getValueFactory() {
			return VF;
		}
	}
